        if (value !== original) changed = true;
        next[offset + channel] = value;
      }
      if (changed) changedBounds = include(changedBounds, x, y);
    }
  }
  return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
}

