  for (let y = workBounds.top; y <= workBounds.bottom; y += 1) {
    for (let x = workBounds.left; x <= workBounds.right; x += 1) {
      const documentPoint = transformPoint(worldTransform, x, y);
      const coverage = selectionCoverage(
        selection,
        documentPoint.x,
        documentPoint.y,
        selectionBuffer,
        selectionRegion,
