export interface NewShapeLayerOptions {
  readonly id: LayerId;
  readonly name: string;
  readonly geometry?: Partial<ShapeGeometry> & Pick<ShapeGeometry, 'width' | 'height'>;
  readonly style?: Partial<ShapeStyle>;
