export const TEXT_ALIGNMENTS = ['left', 'center', 'right'] as const;
export type TextAlign = (typeof TEXT_ALIGNMENTS)[number];

export interface TextStyle {
  readonly fontFamily: string;
  readonly fontSize: number;
