        (stage.clientHeight - margin) / target.canvas.height,
      ),
    );
    setViewport({
      zoom,
      panX: (stage.clientWidth - target.canvas.width * zoom) / 2,
      panY: (stage.clientHeight - target.canvas.height * zoom) / 2,
