  const runCommand = useCallback(
    (
      command: Parameters<CommandHistory<ImageDocument>['execute']>[0],
      dirtyRegions?: readonly PixelRegion[],
    ) => {
      const currentHistory = historyRef.current;
      if (!currentHistory) return undefined;
