      void repository
        .save(document)
        .then(() => {
          if (saveGenerationRef.current !== saveGeneration) return;
          localStorage.setItem(RECENT_DOCUMENT_KEY, document.id);
          setSaveState('saved');
        })
        .catch((error: unknown) => {
          if (saveGenerationRef.current !== saveGeneration) return;
