  it('combines pressure and opacity and treats a zero-size brush as a no-op', () => {
    const mask = createRasterMask(1, 1, new Uint8ClampedArray([0]));
    const patch = paintMaskStroke(mask, identity, [{ x: 0, y: 0, pressure: 0.5 }], {
