                { type: 'line', x: 1, y: 1.5 },
                { type: 'close' },
              ]),
            }),
          ],
        }),
        createAdjustmentLayer({
          id: 'adjustment',
          name: 'Adjustment',
          vectorMask: createVectorMask(4, 4, [
