it('clones pixels from a source onto the destination layer', () => {
  // Source: a 4×4 image with a red cross.
  const sourcePixels = new Uint8ClampedArray(4 * 4 * 4).fill(0);
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
