            output[dstIdx] = sourcePixels[srcIdx];
            output[dstIdx + 1] = sourcePixels[srcIdx + 1];
            output[dstIdx + 2] = sourcePixels[srcIdx + 2];
            output[dstIdx + 3] = sourcePixels[srcIdx + 3];
