  regionLeft: number,
  regionTop: number,
  regionWidth: number,
  pixels: Uint8ClampedArray,
  bounds: Bounds | null,
): PixelPatch {
  if (bounds === null) return emptyPatch();
  const width = bounds.right - bounds.left + 1;
