edits.newText:
it('respects selection when stamping', () => {
  const sourcePixels = new Uint8ClampedArray([255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 0, 255]);
  const source: ClonePixelSource = {
    width: 2,
    height: 2,
    read() {
      return new Uint8ClampedArray(sourcePixels);
    },
  };
  const selectionCoverage = new Uint8ClampedArray(4);
  selectionCoverage[0] = 255; // only top-left selected
  const selection: SelectionMask = {
    width: 2,
    height: 2,
    coverageStore: TiledCoverageStore.fromContiguous(2, 2, selectionCoverage),
  };
  const layer = createPixelLayer({ id: 'a', name: 'A', width: 2, height: 2 });
  const patch = cloneStamp(layer, [{ x: 0, y: 0 }], source, { size: 3, hardness: 1, opacity: 1 }, selection);
  // Only the selected pixel should be changed; patch is cropped to the single changed pixel.
  expect(patch.x).toBe(0);
  expect(patch.y).toBe(0);
  expect(patch.width).toBe(1);
  expect(patch.height).toBe(1);
  expect(Array.from(patch.pixels)).toEqual([255, 0, 0, 255]);
});

