+/**
+ * Stamps source pixels from a `ClonePixelSource` onto a destination pixel layer.
+ *
+ * Each dab samples a region around the document-space source point and paints it
+ * onto the destination using source-over compositing. The brush footprint, hardness,
+ * and opacity behave identically to `paintStroke`.
+ *
+ * `worldTransform` is the layer's world transform used to map document points to
+ * local layer coordinates for the destination. The source is always read in
+ * document space from the provided pixel source.
+ */
+export function cloneStamp(
+  layer: PixelLayer,
+  points: readonly BrushPoint[],
+  source: ClonePixelSource,
+  options: CloneStampOptions,
+  selection?: SelectionMask | null,
+  worldTransform: LayerTransform = layer.transform,
+): PixelPatch {
+  validateLayer(layer);
+  validateTransform(worldTransform);
+  validateSelection(selection);
+  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');
+  assertFinite(options.size, 'Brush size');
+  if (options.size <= 0) throw new RangeError('Brush size must be greater than 0');
+  assertUnit(options.hardness, 'Brush hardness');
+  assertUnit(options.opacity, 'Brush opacity');
+  for (const [index, point] of points.entries()) {
+    assertFinite(point.x, `Stroke point ${String(index)} x`);
+    assertFinite(point.y, `Stroke point ${String(index)} y`);
+    assertUnit(point.pressure ?? 1, `Stroke point ${String(index)} pressure`);
+  }
+
+  const radius = options.size / 2;
+  const inverse = invertTransform(worldTransform);
+  const spacing = Math.max(0.25, radius * 0.5);
+
+  // Build a list of brush dabs by interpolating between input points.
+  const dabs: Array<{ x: number; y: number; pressure: number }> = [];
+  const first = points[0];
+  dabs.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });
+  for (let index = 1; index < points.length; index += 1) {
+    const start = points[index - 1];
+    const end = points[index];
+    const distance = Math.hypot(end.x - start.x, end.y - start.y);
+    const steps = Math.max(1, Math.ceil(distance / spacing));
+    for (let step = 1; step <= steps; step += 1) {
+      const progress = step / steps;
+      dabs.push({
+        x: start.x + (end.x - start.x) * progress,
+        y: start.y + (end.y - start.y) * progress,
+        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
+      });
+    }
+  }
+
+  // Compute the bounding region of the stamp in layer-local coordinates.
+  let strokeBounds: Bounds | null = null;
+  for (const dab of dabs) {
+    strokeBounds = unionBounds(
+      strokeBounds,
+      localDabBounds(worldTransform, inverse, dab.x, dab.y, radius, layer.width, layer.height),
+    );
+  }
+  if (strokeBounds === null || strokeBounds.right < strokeBounds.left) {
+    return emptyPatch();
+  }
+  const regionLeft = strokeBounds.left;
+  const regionTop = strokeBounds.top;
+  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
+  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
+  const next = layer.pixelStore.read({
+    x: regionLeft,
+    y: regionTop,
+    width: regionWidth,
+    height: regionHeight,
+  });
+  const selectionRegion = readSelectionRegion(selection, dabs, radius);
+  let changedBounds: Bounds | null = null;
+
+  for (const dab of dabs) {
+    const bounds = localDabBounds(
+      worldTransform,
+      inverse,
+      dab.x,
+      dab.y,
+      radius,
+      layer.width,
+      layer.height,
+    );
+    const { left, top, right, bottom } = bounds;
+    for (let y = top; y <= bottom; y += 1) {
+      for (let x = left; x <= right; x += 1) {
+        const documentPoint = transformPoint(worldTransform, x, y);
+        const falloff = dabCoverage(
+          Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
+          radius,
+          options.hardness,
+        );
+        const selected = selectionCoverage(
+          selection,
+          documentPoint.x,
+          documentPoint.y,
+          selectionRegion.buffer,
+          selectionRegion.region,
+        );
+        const coverage = falloff * options.opacity * dab.pressure * selected;
+        if (coverage <= 0) continue;
+
+        // Sample from the source at the dab center (document coordinates).
+        const srcX = Math.round(dab.x);
+        const srcY = Math.round(dab.y);
+        const sampleRadius = Math.ceil(radius);
+        const srcRegion = {
+          x: Math.max(0, srcX - sampleRadius),
+          y: Math.max(0, srcY - sampleRadius),
+          width: Math.min(2 * sampleRadius + 1, source.width - Math.max(0, srcX - sampleRadius)),
+          height: Math.min(2 * sampleRadius + 1, source.height - Math.max(0, srcY - sampleRadius)),
+        };
+        if (srcRegion.width <= 0 || srcRegion.height <= 0) continue;
+        const srcPixels = source.read(srcRegion);
+
+        // Map the dab center to local source coordinates.
+        const srcCenterX = srcX - srcRegion.x;
+        const srcCenterY = srcY - srcRegion.y;
+
+        // Compute the local output pixel offset.
+        const dstOffset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
+        const before = [
+          next[dstOffset],
+          next[dstOffset + 1],
+          next[dstOffset + 2],
+          next[dstOffset + 3],
+        ];
+
+        // Determine the source pixel to stamp.
+        const sr = clampIndex(srcCenterX + (x - dab.x), srcRegion.width);
+        const sc = clampIndex(srcCenterY + (y - dab.y), srcRegion.height);
+        const srcPixelOffset = (sc * srcRegion.width + sr) * 4;
+        const spR = srcPixels[srcPixelOffset] ?? 0;
+        const spG = srcPixels[srcPixelOffset + 1] ?? 0;
+        const spB = srcPixels[srcPixelOffset + 2] ?? 0;
+        const spA = srcPixels[srcPixelOffset + 3] ?? 0;
+
+        // Composite source-over: out = src * a_src + dst * a_dst * (1 - a_src).
+        const sa = spA / 255;
+        const da = (before[3] ?? 0) / 255;
+        const outA = Math.min(1, sa + da * (1 - sa)) * 255;
+        if (outA <= 0) continue;
+        const invOutA = 1 - sa;
+        next[dstOffset] = Math.round((spR * sa + before[0] * da * invOutA) / outA);
+        next[dstOffset + 1] = Math.round((spG * sa + before[1] * da * invOutA) / outA);
+        next[dstOffset + 2] = Math.round((spB * sa + before[2] * da * invOutA) / outA);
+        next[dstOffset + 3] = Math.round(outA);
+
+        if (
+          before[0] !== next[dstOffset] ||
+          before[1] !== next[dstOffset + 1] ||
+          before[2] !== next[dstOffset + 2] ||
+          before[3] !== next[dstOffset + 3]
+        ) {
+          changedBounds = include(changedBounds, x, y);
+        }
+      }
+    }
+  }
+  return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
+}
+
